function smartFreeBlock(model){
 if(model.current.id!=='libre')return model;
 const now=Date.now(),next=model.next,limit=next&&next.dayOffset!==1?next.start:Math.min(1440,model.minute+90),available=Math.max(0,limit-model.minute);
 const key='sebasSmartGapV2:'+kyivDay()+':'+limit;
 let state=readStore(key,null);
 if(!state||!Number.isFinite(state.start)||now-state.start>4*3600000){state={start:now,restDone:false};writeStore(key,state)}
 const elapsed=(now-state.start)/60000;
 const remaining=Math.max(0,20-elapsed);
 const followDone=trackData('seguimientos').done;
 let title='Tiempo disponible',minutes=available,kind='free';
 if(!state.restDone&&remaining>0&&available>=remaining+5){title='Descansa '+Math.ceil(remaining)+' minutos';minutes=Math.min(available,remaining);kind='suggested-rest'}
 else if(!followDone&&available>=30){title='Seguimientos prioritarios · 30 min';minutes=30;kind='suggested-task'}
 else if(available>=60){title='KLIMB · avanzar vídeo u oferta';minutes=Math.min(60,available);kind='suggested-task'}
 else if(available>=15){title='Preparar próxima llamada o descansar';minutes=Math.min(available,20);kind='suggested-task'}
 model.current={...model.current,name:title,kind,start:model.minute,end:model.minute+minutes,duration:minutes};
 model.freeGapEnd=limit;return model;
}
function markRestCompletedSilently(){const model=dashboardCommand();const limit=model.freeGapEnd||model.current.end;writeStore('sebasSmartGapV2:'+kyivDay()+':'+limit,{start:Date.now()-20*60000,restDone:true})}
function markRestCompleted(){const model=dashboardCommand();const limit=model.freeGapEnd||model.current.end;writeStore('sebasSmartGapV2:'+kyivDay()+':'+limit,{start:Date.now()-20*60000,restDone:true});view('hoy',true)}
function smartGapOptions(){const model=dashboardCommand();const until=model.freeGapEnd||model.current.end;const minutes=Math.max(0,until-SebasPlanner.minute());return [{id:'descanso',label:'Descansar 20 min',min:10},{id:'seguimientos',label:'Seguimientos · 30 min',min:30,done:trackData('seguimientos').done},{id:'ingles',label:'Inglés · 60 min',min:60},{id:'klimb',label:'KLIMB · vídeo, oferta o prospección',min:30},{id:'preparacion',label:'Preparar próxima llamada · 15 min',min:15}].filter(x=>minutes>=x.min&&!x.done)}
function openSmartActivity(){const model=dashboardCommand(),available=Math.max(0,(model.freeGapEnd||model.current.end)-model.minute);const choices=smartGapOptions();const overlay=document.createElement('div');overlay.id='smart-activity-overlay';overlay.style.cssText='position:fixed;inset:0;background:#0009;z-index:9999;display:flex;align-items:flex-end;justify-content:center;padding:18px';overlay.innerHTML='<section role="dialog" aria-modal="true" aria-label="Elegir actividad" style="background:#fff;color:#171717;border-radius:24px;padding:22px;width:min(100%,460px);max-height:80vh;overflow:auto"><h2>¿Qué quieres hacer ahora?</h2><p>Tienes '+available+' minutos hasta el siguiente bloque. Elige sin salir del Centro de Mando.</p>'+choices.map(x=>'<button style="display:block;width:100%;margin:8px 0;padding:15px;text-align:left;border:1px solid #ddd;border-radius:12px;background:#f6f6f6;color:#171717" onclick="chooseSmartActivity(\''+x.id+'\')">'+esc(x.label)+'</button>').join('')+'<button style="padding:12px" onclick="document.getElementById(\'smart-activity-overlay\').remove()">Cerrar</button></section>';overlay.addEventListener('click',e=>{if(e.target===overlay)overlay.remove()});document.body.appendChild(overlay)}
function chooseSmartActivity(id){document.getElementById('smart-activity-overlay')?.remove();if(id==='descanso'){const m=dashboardCommand();const key='sebasSmartGapV2:'+kyivDay()+':'+(m.freeGapEnd||m.current.end);writeStore(key,{start:Date.now(),restDone:false});view('hoy',true);return}if(id==='seguimientos'){markRestCompletedSilently();beginTrack('seguimientos');view('hoy',true);return}if(id==='ingles'){beginTrack('ingles');view('hoy',true);return}if(id==='klimb'){beginTrack('klimb');view('hoy',true);return}view('hoy',true)}

/* Time-aware dashboard and guided activities. Provider data stays in memory. */
let routineChooserOpen=false;let speechRun=0;let selectedActivity='oracion',focusedEventKey='',chosenVideo='3EKcdVsYdk4',researchApiKey='',researchState={connected:false,status:'Sin conectar',events:[],cards:[],lastSync:null},researchBusy=false,noticeBaseline=null,lastDashboardMinute=-1;
const JAEHO_VIDEOS=[
 {id:'3EKcdVsYdk4',embedBlocked:true,name:'Cuerpo completo · 25 min',seconds:1487,type:'full'},
 {id:'thomPOFkXYM',embedBlocked:true,name:'Cuerpo completo · 30 min',seconds:1783,type:'full'},
 {id:'D904TqLmLVw',name:'Cuerpo completo · principiantes',seconds:1214,type:'beginner'},
 {id:'BGXGdUj93BM',name:'Cuerpo completo · sin saltos',seconds:886,type:'beginner'},
 {id:'8g0POqhtUd8',name:'Calentamiento dinámico',seconds:454,type:'warmup'},
 {id:'QZS3cbXJaHc',name:'Abdominales · principiantes',seconds:432,type:'core'}
];
function jsArg(value){return esc(JSON.stringify(value))}
function effectiveEvents(){const map=new Map();for(const event of [...researchState.events.filter(e=>!Array.isArray(allowedCalendarIds)||allowedCalendarIds.includes(e.calendarId)),...googleEvents]){const key=SebasCore.eventKey(event),old=map.get(key);if(!old||Date.parse(event.updated||0)>=Date.parse(old.updated||0)||googleEvents.includes(event))map.set(key,event)}return SebasRecap.merge([...map.values()],recapState.events.map(x=>({...x})))}
function plannerOptions(){return {busyEvents:effectiveEvents(),mealTimes:data.mealTimes?.[kyivDay()]||{},mealDate:kyivDay(),mealNames:Object.fromEntries(dailyFood().map(m=>[m.type,m.name])),gym:data.gymMinutes||40,starts:data.routineStarts||{},names:Object.fromEntries(TRACKS.map(t=>[t.id,t.name])),englishWeekday:data.englishWeekday??3,goals:Object.fromEntries(TRACKS.map(t=>[t.id,t.goal]))}}
function dashboardCommand(){const model=SebasPlanner.command(effectiveEvents(),{...Object.fromEntries(TRACKS.map(t=>[t.id,trackData(t.id).done]))},activeTrack,Date.now(),plannerOptions());return smartFreeBlock(model)}
function activityTab(id){return id==='gym'?'gym':id==='lectura'?'lectura':['desayuno','almuerzo','snackam','snackpm','cena'].includes(id)?'comidas':['descanso','postcall','despertar'].includes(id)?'actividad':TRACKS.some(t=>t.id===id)?'actividad':'impulso'}
function openActivity(id){if(id==='ingles'){openLearning('english');return}if(id==='ventas'){openLearning('sales');return}if(id==='klimb'){view('proyectos');return}if(id==='cena'){openFood(chosenFood('dinner').id);return}if(['desayuno','almuerzo','snackam','snackpm','cena'].includes(id))mealCategory=id==='cena'?'dinner':id==='almuerzo'?'lunch':id==='desayuno'?'breakfast':'snacks';selectedActivity=id;view(activityTab(id))}
function openEvent(key){focusedEventKey=key;closingMode='calls';view('impulso');const event=effectiveEvents().find(e=>SebasCore.eventKey(e)===key);if(event&&SebasLife.isCommercial(event))openCallReport(key)}
function openCommand(which){const item=dashboardCommand()[which];if(!item)return;if(item.kind==='event')openEvent(SebasCore.eventKey(item.event));else openActivity(item.id)}
function actionCaption(item){if(item.kind==='event')return 'Ver sesión e investigación';if(item.id==='gym')return 'Preparar mi entrenamiento';if(item.id==='lectura')return 'Leer '+TRACKS.find(t=>t.id==='lectura').goal+' minutos';if(['desayuno','almuerzo','snackam','snackpm','cena'].includes(item.id))return 'Ver mi comida';if(item.id==='libre')return 'Elegir una actividad';if(item.id==='descanso')return 'Tomar un descanso';if(['trabajo','preparacion','daily'].includes(item.id))return 'Ver mis llamadas';return 'Abrir actividad'}
function safeLink(value,kind='source'){try{const u=new URL(value);if(u.protocol!=='https:'||u.username||u.password)return '';if(kind==='instagram'&&!['instagram.com','www.instagram.com'].includes(u.hostname))return '';if(kind==='slack'&&!u.hostname.endsWith('.slack.com'))return '';if(kind==='meeting'&&!/^(meet\.google\.com|([\w-]+\.)?zoom\.us|teams\.microsoft\.com)$/.test(u.hostname))return '';return u.href}catch{return ''}}
function homeDashboard(){const pendingCalls=effectiveEvents().filter(e=>SebasCore.onDay(e)&&SebasLife.isCommercial(e)&&!SebasLife.scheduledEvents([e],allLeadCards()).length).length;const model=dashboardCommand(),now=model.current,next=model.next;const pending=orderedHabitTracks();const done=pending.filter(t=>trackData(t.id).done).length;return `
${commandDay(model)}<div id="time-alert-notice" role="status"></div>
${priorityDashboard()}
<button class="routine-shortcut" onclick="view('habitos')">Rutina y registros <span aria-hidden="true">→</span></button>`}
function timerPanel(id){const t=TRACKS.find(t=>t.id===id);if(!t)return '';const seconds=currentSeconds(id),goal=t.goal*60,running=activeTrack?.id===id,done=trackData(id).done;return `<section class="activity-timer"><span class="eyebrow">${running?'EN CURSO':done?'COMPLETADO':'TU MOMENTO'}</span><h2>${esc(t.name)}</h2><div class="countdown" ${done?'':`data-countdown="${id}" data-target="${goal}"`}>${formatTime(done?seconds:Math.max(0,goal-seconds))}</div><p class="timer-meta"><span data-track-seconds="${id}">${formatTime(seconds)}</span> dedicados · objetivo ${goal/60} min</p><div class="timer-progress"><span data-timer-progress="${id}" data-target="${goal}" style="width:${Math.min(100,seconds/goal*100)}%"></span></div><div class="actions">${done?`<button onclick="undoTrack('${id}')">Reabrir actividad</button>`:`<button onclick="${running?'pauseTrack()':`beginTrack('${id}')`}">${running?'Pausar':'▶ '+(seconds?'Continuar':'Empezar')}</button><button class="lightbtn" onclick="finishTrack('${id}')">Terminar</button>`}</div></section>`}
function activityDashboard(){if(selectedActivity==='ducha')return '<section class="card"><h2>Ducha y preparación</h2><button onclick="view(\'hoy\')">Volver a Hoy</button></section>';if(selectedActivity==='despertar')return '<section class="card"><h2>Despertar y prepararte</h2><p>06:45. A las 07:00 empieza tu oración de diez minutos.</p><button onclick="view(\'hoy\')">Volver a mi día</button></section>';if(['descanso','postcall'].includes(selectedActivity))return '<section class="card"><h2>Desconexión y descanso</h2><p>Termina la jornada y recupera energía. El descanso no se registra como hábito.</p><button onclick="view(\'hoy\')">Volver a mi día</button></section>';return timerPanel(selectedActivity)+`<button class="lightbtn" onclick="view('hoy')">Volver a mi día</button>`}
function chooseWorkout(minutes){if(activeTrack?.id==='gym'){return}data.gymMinutes=minutes;TRACKS.find(t=>t.id==='gym').goal=minutes;data.gymSession=null;save();view('gym')}
function workoutElapsed(){const session=data.gymSession;return session?.day===kyivDay()?Math.max(0,currentSeconds('gym')-session.baseline):0}
function startWorkout(){const minutes=data.gymMinutes||40,place=trainingPlace(),group=place==='gym'?gymGroupToday():'full';let session=data.gymSession;if(trackData('gym').done)session=null;if(!session||session.day!==kyivDay()||session.minutes!==minutes||(session.place||'home')!==place||(session.group||'full')!==group){data.gymSession={day:kyivDay(),minutes,place,group,baseline:currentSeconds('gym'),exerciseIndex:0,completedSets:{},restFromSeconds:null};save()}if(trackData('gym').done){const rec=trackData('gym');rec.done=false;tracked[kyivDay()]??={};tracked[kyivDay()].gym=rec;storeTracks()}beginTrack('gym')}
function chooseVideo(id){if(!JAEHO_VIDEOS.some(v=>v.id===id))return;chosenVideo=id;const slot=document.getElementById('video-slot');if(slot)slot.innerHTML=videoPlayer(id)}
function videoPlayer(id){const video=JAEHO_VIDEOS.find(v=>v.id===id);if(!video)return '';if(video.embedBlocked)return `<div class="video-fallback"><span class="play-dot">▶</span><h3>${esc(video.name)}</h3><p>Este vídeo del canal tiene desactivada la reproducción en otras webs.</p><a class="external-video" href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener">Abrir rutina en YouTube ↗</a><small>Duración: ${formatTime(video.seconds)}. Tu cronómetro puede seguir en SEBAS OS.</small></div>`;return `<div class="video-wrap"><iframe src="https://www.youtube-nocookie.com/embed/${id}?playsinline=1&rel=0" title="Jaeho Fitness · ${esc(video.name)}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div><p class="muted">Vídeo original de Jaeho Fitness · ${formatTime(video.seconds)}. <a href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener">Abrir en YouTube ↗</a></p>`}
function trainingPlace(){return data.trainingPlace==='gym'?'gym':'home'}
function gymGroupToday(){const override=data.gymRoutineOverride;return override?.day===kyivDay()&&SebasPlanner.GYM_GROUPS[override.group]?override.group:SebasPlanner.gymGroup()}
function trainingPlan(){return SebasPlanner.workout(data.gymMinutes||40,{mode:trainingPlace(),group:gymGroupToday()})}
function chooseTrainingPlace(place){if(!['home','gym'].includes(place)||activeTrack?.id==='gym'||trainingPlace()===place)return;routineChooserOpen=false;data.trainingPlace=place;data.gymSession=null;save();view('gym')}
function chooseGymRoutine(group){if(!SebasPlanner.GYM_GROUPS[group]||activeTrack?.id==='gym')return;routineChooserOpen=false;data.trainingPlace='gym';data.gymRoutineOverride={day:kyivDay(),group};data.gymSession=null;save();view('gym')}
function currentGymPhase(plan){if(trackData('gym').done)return {kind:'done',name:'Sesión terminada',left:0,index:0};const elapsed=workoutElapsed();if(plan.mode!=='gym')return SebasPlanner.phase(plan,elapsed);const session=data.gymSession;if(!session?.warmupDone&&elapsed<300)return {kind:'warmup',name:'Calentamiento suave',left:300-elapsed,index:0};const index=Math.min(session?.exerciseIndex||0,plan.exercises.length-1),rest=session?.restFromSeconds;const remaining=rest===null||rest===undefined?0:Math.max(0,plan.restSeconds-(elapsed-rest));return {kind:remaining?'rest':'work',name:remaining?'Descanso entre series':plan.exercises[index].name,left:remaining||Math.max(0,plan.total-elapsed),index}}
function gymWarmupDone(){if(activeTrack?.id!=='gym'||!data.gymSession)return;data.gymSession.warmupDone=true;save();view('gym')}
function markGymSet(){const plan=trainingPlan(),session=data.gymSession;if(plan.mode!=='gym'||!session||activeTrack?.id!=='gym'||currentGymPhase(plan).kind!=='work')return;const index=Math.min(session.exerciseIndex||0,plan.exercises.length-1),exercise=plan.exercises[index];session.completedSets??={};session.completedSets[exercise.id]=Math.min(plan.sets,(session.completedSets[exercise.id]||0)+1);session.restFromSeconds=workoutElapsed();save();view('gym')}
function moveGymExercise(delta){const plan=trainingPlan();if(plan.mode!=='gym'||!data.gymSession)return;data.gymSession.exerciseIndex=Math.max(0,Math.min(plan.exercises.length-1,(data.gymSession.exerciseIndex||0)+delta));save();view('gym')}
function skipGymRest(){if(!data.gymSession)return;data.gymSession.restFromSeconds=null;save();view('gym')}
function gymSetControls(plan,phase){const session=data.gymSession,index=Math.min(session?.exerciseIndex||0,plan.exercises.length-1),exercise=plan.exercises[index],completed=session?.completedSets?.[exercise.id]||0;return `<div class="gym-set-panel"><p class="eyebrow">EJERCICIO ${index+1} DE ${plan.exercises.length}</p><h3>${esc(exercise.name)}</h3><p>Objetivo: ${esc(exercise.reps)}${/\bs\b|min/.test(exercise.reps)?'':' repeticiones'} · ${plan.sets} series</p><div class="set-dots" aria-label="${completed} de ${plan.sets} series registradas">${Array.from({length:plan.sets},(_,i)=>`<span class="${i<completed?'set-complete':''}">${i<completed?'✓':i+1}</span>`).join('')}</div><button data-mark-set onclick="markGymSet()" ${activeTrack?.id!=='gym'||phase.kind!=='work'||completed>=plan.sets?'disabled':''}>${completed>=plan.sets?'Series registradas':'✓ Serie hecha'}</button>${phase.kind==='warmup'?`<button class="lightbtn" data-warmup-done onclick="gymWarmupDone()" ${activeTrack?.id==='gym'?'':'disabled'}>Calentamiento listo</button>`:''}${phase.kind==='rest'?'<button class="lightbtn" onclick="skipGymRest()">Omitir descanso</button>':''}<div class="exercise-nav"><button class="lightbtn" onclick="moveGymExercise(-1)" ${!session||index===0?'disabled':''}>← Anterior</button><button class="lightbtn" onclick="moveGymExercise(1)" ${!session||index===plan.exercises.length-1?'disabled':''}>Siguiente →</button></div><small>Marca solo las series que hayas realizado. Las repeticiones son un objetivo, no un registro automático.</small></div>`}
function toggleRoutineChooser(){routineChooserOpen=!routineChooserOpen;view('gym')}
function gymDashboard(){
 const plan=trainingPlan(),phase=currentGymPhase(plan),session=data.gymSession?.day===kyivDay(),done=trackData('gym').done,place=trainingPlace(),running=activeTrack?.id==='gym';
 const choices=place==='gym'?`<button class="routine-change-button" aria-expanded="${routineChooserOpen}" onclick="toggleRoutineChooser()" ${running?'disabled':''}>Cambiar rutina</button>`:'';
 const menu=place==='gym'&&routineChooserOpen?`<div class="routine-options">${Object.entries(SebasPlanner.GYM_GROUPS).map(([id,group])=>`<button class="${plan.group===id?'chosen':''}" onclick="chooseGymRoutine('${id}')" ${running?'disabled':''}>${esc(group.name)}</button>`).join('')}<span class="routine-help">Solo para hoy. Mañana vuelve la distribución semanal.</span></div>`:'';
 return `<section class="card gym-intro"><div class="place-picker" role="group" aria-label="Lugar del entrenamiento"><button aria-pressed="${place==='home'}" onclick="chooseTrainingPlace('home')" ${running?'disabled':''}>En casa</button><button aria-pressed="${place==='gym'}" onclick="chooseTrainingPlace('gym')" ${running?'disabled':''}>En gimnasio</button></div><span class="eyebrow">${place==='home'?'TU ENTRENAMIENTO EN CASA':'RUTINA DE HOY · '+esc(new Intl.DateTimeFormat('es',{timeZone:'Europe/Kyiv',weekday:'long'}).format(new Date()))}</span><div class="routine-heading"><h2>${place==='gym'?esc(plan.name):'Circuito en casa · cuerpo completo'}</h2>${choices}</div>${menu}<p class="muted">${place==='gym'?esc(plan.detail)+' · ejercicios, series y descansos.':'Vídeos de Jaeho y circuito guiado. Elige cuánto tiempo tienes.'}</p><div class="duration-picker" role="group" aria-label="Duración del entrenamiento">${[30,40,45,60].map(n=>`<button aria-pressed="${plan.minutes===n}" ${running?'disabled':''} onclick="chooseWorkout(${n})">${n===60?'1 hora':n+' min'}</button>`).join('')}</div><div class="session-facts"><span><b>${plan.exercises.length}</b> ejercicios</span><span><b>${plan.mode==='gym'?plan.sets:plan.rounds}</b> ${plan.mode==='gym'?'series / ejercicio':'rondas'}</span><span><b>${plan.mode==='gym'?'75 s':'40 / 20'}</b> ${plan.mode==='gym'?'descanso orientativo':'trabajo / pausa'}</span></div><p class="muted">${place==='gym'?'Tiempo reservado: '+plan.minutes+' min. Incluye calentamiento; adapta el peso y el descanso a tu nivel.':'5 min para calentar + '+(plan.minutes-10)+' min de circuito + 5 min para bajar el ritmo.'}</p></section>
 <section class="activity-timer"><span class="eyebrow">${done?'COMPLETADO':running?'EN CURSO':session?'SESIÓN GUARDADA':'LISTO CUANDO TÚ QUIERAS'}</span><h2 data-gym-phase>${esc(phase.name)}</h2><div class="countdown" data-gym-countdown>${formatTime(phase.left)}</div><p class="timer-meta" data-gym-detail>${plan.mode==='gym'?(phase.kind==='rest'?'Descanso · ':'Tiempo reservado · '):phase.round?'Ronda '+phase.round+' de '+plan.rounds+' · ':'Muévete a tu ritmo · '}${formatTime(Math.max(0,plan.total-workoutElapsed()))} de sesión</p><div class="actions"><button onclick="${running?'pauseTrack()':'startWorkout()'}">${done?'Nueva sesión':running?'Pausar':session?'Continuar entrenamiento':'▶ Empezar entrenamiento'}</button>${session&&!done?'<button class="lightbtn" onclick="finishTrack(\'gym\')">Terminar sesión</button>':''}</div>${place==='gym'&&!done?gymSetControls(plan,phase):''}</section>
 <details class="card"><summary>${place==='gym'?'Ver rutina completa':'Ver circuito'} · ${plan.exercises.length} ejercicios</summary><p class="muted">${place==='gym'?'Rutina orientativa de SEBAS OS. Usa una carga que puedas controlar y pide ayuda al equipo del gimnasio si no conoces la técnica.':'Circuito propio de SEBAS OS, independiente de las rutinas del canal.'}</p>${plan.exercises.map((e,i)=>`<article class="exercise-row" data-exercise="${i}"><span class="exercise-number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(e.name)}</h3><p>${esc(e.hint)}</p><small>${place==='gym'?plan.sets+' series · '+esc(e.reps)+' · descanso ~75 s':plan.rounds+' rondas · 40 s de trabajo / 20 s de pausa'}</small></div></article>`).join('')}<p class="muted">Interrumpe si aparece dolor. No necesitas completar todas las series.</p></details>
 ${place==='home'?`<section class="card"><div class="sectiontop"><h2>Entrena con Jaeho</h2><a href="https://www.youtube.com/@jaeho_fitness" target="_blank" rel="noopener">Canal ↗</a></div><p class="muted">Rutinas originales completas. La reproducción aquí depende de los permisos del canal; siempre tienes el enlace a YouTube. El circuito propio es independiente.</p><div id="video-slot">${videoPlayer(chosenVideo)}</div><div class="video-library">${JAEHO_VIDEOS.map(v=>`<button class="video-choice" onclick="chooseVideo('${v.id}')"><span class="play-dot">▶</span><span><strong>${esc(v.name)}</strong><small>${formatTime(v.seconds)} · Jaeho Fitness</small></span></button>`).join('')}</div></section>`:`<details class="card"><summary>Distribución semanal</summary><p class="muted">Lunes: empuje · Martes: pierna · Miércoles: tirón · Jueves: movilidad · Viernes: torso · Sábado: core · Domingo: recuperación. Puedes cambiar el grupo de hoy.</p></details>`}`;
}
function updateGymUI(){const plan=trainingPlan(),phase=currentGymPhase(plan),title=document.querySelector('[data-gym-phase]'),clock=document.querySelector('[data-gym-countdown]'),detail=document.querySelector('[data-gym-detail]');if(title)title.textContent=phase.name;if(clock)clock.textContent=formatTime(phase.left);if(detail)detail.textContent=(plan.mode==='gym'?(phase.kind==='rest'?'Descanso · ':'Tiempo reservado · '):phase.round?'Ronda '+phase.round+' de '+plan.rounds+' · ':'Muévete a tu ritmo · ')+formatTime(Math.max(0,plan.total-workoutElapsed()))+' de sesión';document.querySelectorAll('[data-exercise]').forEach(e=>e.classList.toggle('exercise-current',Number(e.dataset.exercise)===phase.index&&phase.kind==='work'));const mark=document.querySelector('[data-mark-set]');if(mark){const exercise=plan.exercises[phase.index];mark.disabled=activeTrack?.id!=='gym'||phase.kind!=='work'||(data.gymSession?.completedSets?.[exercise.id]||0)>=plan.sets}const warmup=document.querySelector('[data-warmup-done]');if(warmup)warmup.hidden=phase.kind!=='warmup';}

function leadCard(event){return allLeadCards().find(x=>x.eventKey===SebasCore.eventKey(event))}
function eventResearch(event){const card=leadCard(event),confirmed=card?.confirmed===true&&card.eventUpdated===event.updated&&card.sessionStart===event.start,key=SebasCore.eventKey(event),ig=safeLink(card?.instagram,'instagram'),session=SebasOps.session(event,card);return `<article class="call-preview ${confirmed?'':'call-pending'}"><div class="call-time"><strong>${SebasPlanner.time(SebasPlanner.minute(Date.parse(event.start)))}</strong><span>${SebasPlanner.time(SebasPlanner.minute(Date.parse(event.end)))}</span></div><div class="call-preview-body"><span class="call-state">${confirmed?'CONFIRMADA':'POR CONFIRMAR'} · ${Math.round((Date.parse(event.end)-Date.parse(event.start))/60000)} MIN</span><h2>${esc(session.name)}</h2><p>${esc(session.label)}</p><div class="call-preview-actions"><button onclick="openCallReport(${jsArg(key)})">Ver informe</button>${ig?`<a href="${esc(ig)}" target="_blank" rel="noopener">Instagram ↗</a>`:''}</div></div></article>`}
function impulsoDashboard(){const focused=effectiveEvents().find(e=>SebasCore.eventKey(e)===focusedEventKey);if(focused&&!SebasLife.isCommercial(focused))return `<section class="card"><span class="eyebrow">EVENTO PERSONAL</span><h2>${esc(focused.name)}</h2><p>${esc(new Intl.DateTimeFormat('es',{timeZone:'Europe/Kyiv',dateStyle:'full',timeStyle:'short'}).format(new Date(focused.start)))}</p><button onclick="view('calendario')">Volver al calendario</button></section>`;const calls=effectiveEvents().filter(e=>!e.allDay&&(SebasCore.onDay(e)||SebasCore.eventKey(e)===focusedEventKey)&&SebasLife.isCommercial(e)),confirmed=SebasLife.scheduledEvents(calls,allLeadCards()),keys=new Set(confirmed.map(SebasCore.eventKey)),pending=calls.filter(e=>!keys.has(SebasCore.eventKey(e))),next=confirmed.find(e=>Date.parse(e.end)>Date.now()),minutes=confirmed.reduce((n,e)=>n+(Date.parse(e.end)-Date.parse(e.start))/60000,0);return `<section class="destination-hero calls-hero"><div class="destination-top"><span class="eyebrow">CLOSING · TU DÍA COMERCIAL</span><span class="source-pill">${recapDevice?'RECAP':'AGENDA'}</span></div><h2>Una llamada.<br>Una oportunidad.</h2><div class="destination-metrics"><div><strong>${confirmed.length}</strong><span>llamadas confirmadas</span></div><div><strong>${Math.floor(minutes/60)}<small>h ${Math.round(minutes%60)}m</small></strong><span>en sesiones</span></div></div><div class="destination-bottom"><span>${next?'Siguiente · '+SebasPlanner.time(SebasPlanner.minute(Date.parse(next.start))):'Tu agenda, a un vistazo'}</span><button class="hero-mini-action" onclick="openSaleDialog()">+ Añadir venta</button></div></section><div class="sectiontop calls-list-heading"><h2>Mis llamadas de hoy</h2>${recapDevice?recapUpdateControls():researchApiKey?'<button class="tinybutton" onclick="syncResearch(true)">Actualizar</button>':''}</div><p class="sync-caption" role="status">${esc(recapDevice?recapState.status:researchState.status)}</p>${recapState.error?'<p class="sync-error" role="alert">'+esc(recapState.error)+'</p>':''}${confirmed.length?confirmed.map(eventResearch).join(''):`<section class="card empty-state"><span class="empty-symbol" aria-hidden="true">◴</span><h3>${recapDevice?'A la espera del recap':'Tu próxima llamada empieza aquí'}</h3><p>${recapDevice?'Cuando llegue tu agenda, tendrás cada sesión con su informe.':'Conecta tu agenda privada para ver las llamadas y sus informes.'}</p>${!recapDevice?'<button onclick="view(\'ajustes\')">Conectar agenda</button>':''}</section>`}${pending.length?`<details class="card" ${sectionAttrs('pending-calls')}><summary>${pending.length} reserva${pending.length===1?'':'s'} por confirmar</summary>${pending.map(eventResearch).join('')}</details>`:''}`}
function readLead(key){const card=allLeadCards().find(x=>x.eventKey===key);if(!card?.summary)return;if(!window.speechSynthesis||!window.SpeechSynthesisUtterance){const status=document.getElementById('voice-status');if(status)status.textContent='La lectura en voz alta no está disponible en este navegador.';return}stopReading();const run=speechRun,words=String(card.summary).split(/\s+/),chunks=[];let chunk='';for(const word of words){if(chunk.length+word.length>220&&chunk){chunks.push(chunk);chunk=''}chunk+=(chunk?' ':'')+word}if(chunk)chunks.push(chunk);let index=0;const speak=()=>{if(run!==speechRun||index>=chunks.length)return;const utterance=new window.SpeechSynthesisUtterance(chunks[index++]);utterance.lang='es-ES';utterance.rate=1;utterance.onend=speak;window.speechSynthesis.speak(utterance)};speak()}
function stopReading(){speechRun++;window.speechSynthesis?.cancel()}

let slackConnection={configured:false,connected:false,message:'Pendiente de activar el servicio de Slack'},slackAuthWindow=null,slackPoll=null;
function slackSettings(){return `<section class="card slack-connection"><span class="eyebrow">CONEXIÓN DIRECTA</span><h2>Slack</h2><p role="status" id="slack-state">${esc(slackConnection.message)}</p>${slackConnection.connected?`<p class="muted">${esc(slackConnection.team||'Slack')} · solo lectura</p><label>Canal de investigación<input id="slack-channel" placeholder="avisos-comerciales" value="${esc(slackConnection.channel||'')}" maxlength="80"></label><div class="actions"><button onclick="saveSlackChannel()">Guardar canal</button><button class="lightbtn" onclick="disconnectSlack()">Desconectar Slack</button></div>`:`<button onclick="connectSlack()" ${!researchApiKey||!slackConnection.configured?'disabled':''}>Conectar con Slack ↗</button>`}<p id="slack-message" role="status"></p>${!slackConnection.configured?'<p class="muted">La autorización estará disponible al activar Slack en el servicio privado.</p>':''}</section>`}
async function refreshSlackConnection(){if(!researchApiKey)return;try{slackConnection=await privateApi('/api/slack/status')}catch{slackConnection={configured:false,connected:false,message:'No se pudo verificar Slack. Revisa la conexión al servicio.'}}if(activeTab==='ajustes')view('ajustes',true)}
async function connectSlack(){if(!researchApiKey||!slackConnection.configured)return;slackAuthWindow=window.open('about:blank','sebas-slack-oauth','width=640,height=760');if(!slackAuthWindow){document.getElementById('slack-message').textContent='Permite la ventana de autorización y vuelve a intentarlo.';return}try{const result=await privateApi('/api/slack/start',{method:'POST',body:'{}'}),url=new URL(result.url);if(url.origin!=='https://slack.com'||url.pathname!=='/oauth/v2/authorize')throw Error('Enlace de autorización no válido.');slackAuthWindow.location=url.href;clearInterval(slackPoll);const stop=Date.now()+300000;slackPoll=setInterval(()=>{if(slackAuthWindow?.closed||Date.now()>stop){clearInterval(slackPoll);refreshSlackConnection()}},1500)}catch(e){slackAuthWindow.close();document.getElementById('slack-message').textContent=e.message}}
if(typeof window.addEventListener==='function')window.addEventListener('message',event=>{if(!data.researchUrl||event.origin!==new URL(data.researchUrl).origin||event.source!==slackAuthWindow||event.data?.type!=='sebas-slack-result')return;clearInterval(slackPoll);refreshSlackConnection()});
async function saveSlackChannel(){const channel=document.getElementById('slack-channel').value;try{await privateApi('/api/slack/channel',{method:'POST',body:JSON.stringify({channel})});await refreshSlackConnection()}catch(e){document.getElementById('slack-message').textContent=e.message}}
async function disconnectSlack(){try{await privateApi('/api/slack/disconnect',{method:'POST',body:'{}'});researchState.cards=[];await refreshSlackConnection()}catch(e){document.getElementById('slack-message').textContent=e.message}}
function researchSettings(){return `<section class="card"><h2>Investigación de llamadas</h2><p role="status">${esc(researchState.status)}</p><p class="muted">Conecta tu servidor privado de SEBAS OS. La conexión de Slack de ChatGPT no se transfiere a esta app. No pegues aquí tokens de Slack ni secretos de Google.</p><label>URL del servicio privado<input id="research-url" type="url" placeholder="https://tu-servidor.example" value="${esc(data.researchUrl||'')}"></label><p><label>Clave de acceso del servicio<input id="research-key" type="password" autocomplete="off" placeholder="Solo se conserva mientras la app está abierta"></label></p><div class="actions"><button onclick="connectResearch()">Conectar servicio</button><button class="lightbtn" onclick="disconnectResearch()">Desconectar</button><button onclick="enablePush()" ${researchState.connected?'':'disabled'}>Activar notificaciones</button></div><p id="research-message" role="status"></p><p class="muted">Sin un servidor configurado, no hay sincronización de Slack ni notificaciones con la app cerrada. Google en esta app sigue funcionando por separado.</p></section>`}
function routineSettings(){return bedtimeSettings()+'<section class="card"><h2>Planificación semanal</h2><p>Despertar y prepararte 20 min → oración → entrenamiento → lectura → desayuno → ducha y preparación.</p><p>Inglés: una hora sábado y domingo a las 09:00, y una mañana entre semana de 08:30 a 09:30. Propuestas según tus huecos; no son reservas de clases.</p><label>Mañana de inglés<select onchange="data.englishWeekday=Number(this.value);save();view(\'ajustes\',true)">'+[1,2,3,4,5].map((d,i)=>'<option value="'+d+'" '+((data.englishWeekday??3)===d?'selected':'')+'>'+['Lunes','Martes','Miércoles','Jueves','Viernes'][i]+'</option>').join('')+'</select></label><p>Daily 10:00. Preparación 09:40. Inglés termina 30 min antes del daily. Martes y viernes: Closing hasta las 18:30; después KLIMB. Mentoría de ventas: martes 20:00–21:00. Práctica comercial: sábado 15:00–16:00.</p><p class="muted">Los eventos reales sustituyen los bloques propuestos que coincidan.</p></section>'}
function saveRoutineHours(){}
async function privateApi(path,options={}){if(!data.researchUrl||!researchApiKey)throw Error('Conecta tu servicio privado en Ajustes.');const response=await fetch(data.researchUrl+path,{...options,headers:{Authorization:'Bearer '+researchApiKey,'Content-Type':'application/json',...(options.headers||{})},cache:'no-store',signal:AbortSignal.timeout(25000)});if(!response.ok)throw Error(response.status===401?'La clave de acceso no es válida.':'El servicio no pudo completar la consulta ('+response.status+').');return response.json()}
async function connectResearch(){const input=document.getElementById('research-url').value.trim().replace(/\/$/,'');try{const url=new URL(input);if(url.protocol!=='https:'&&!(url.protocol==='http:'&&['localhost','127.0.0.1','terminal.local'].includes(url.hostname)))throw Error();if(url.username||url.password||url.search||url.hash||url.pathname!=='/')throw Error();}catch{document.getElementById('research-message').textContent='Usa la URL HTTPS de tu servicio privado, sin rutas ni parámetros.';return}researchApiKey=document.getElementById('research-key').value;data.researchUrl=input;save();await syncResearch(true);await refreshSlackConnection()}
async function syncResearch(force=false){if(researchBusy)return;if(!researchApiKey){researchState.status='Servicio privado sin conectar';if(force)view('ajustes');return}researchBusy=true;researchState.status='Sincronizando investigación…';try{if(force)await privateApi('/api/sync',{method:'POST',body:'{}'});const result=await privateApi('/api/today');researchState={connected:true,status:result.status||'Conectado al servicio privado',events:Array.isArray(result.events)?result.events:[],cards:Array.isArray(result.cards)?result.cards:[],lastSync:result.lastSync||Date.now()};notifySameDay(researchState.events);}catch(e){researchState.connected=false;researchState.status=e.message+' Se conserva la última consulta.';}finally{researchBusy=false;if(['hoy','impulso','ajustes'].includes(activeTab))view(activeTab)}}
async function disconnectResearch(){if(navigator.serviceWorker){try{const registration=await navigator.serviceWorker.getRegistration();const subscription=await registration?.pushManager?.getSubscription();if(subscription){if(researchApiKey)await privateApi('/api/push/subscriptions',{method:'DELETE',body:JSON.stringify({endpoint:subscription.endpoint})});await subscription.unsubscribe()}}catch{calendarNotice='La conexión local se ha cerrado; no se pudo confirmar la baja de notificaciones en el servidor.'}}researchApiKey='';slackConnection={configured:false,connected:false,message:'Servicio privado sin conectar'};researchState={connected:false,status:'Sin conectar',events:[],cards:[],lastSync:null};noticeBaseline=null;stopReading();view('ajustes')}
function notifySameDay(events){const now=Date.now(),m=SebasPlanner.minute(now);const keys=new Set(events.filter(e=>SebasCore.onDay(e)&&Date.parse(e.start)>now).map(SebasCore.eventKey));if(noticeBaseline&&m>=360&&m<1260){const added=events.filter(e=>keys.has(SebasCore.eventKey(e))&&!noticeBaseline.has(SebasCore.eventKey(e)));if(added.length)calendarNotice='Te han puesto '+added.length+' sesión nueva hoy. Abre Impulso para ver su investigación.';}noticeBaseline=keys}
async function enablePush(){try{if(!('PushManager'in window)||!('Notification'in window))throw Error('Este navegador no ofrece notificaciones push. En iPhone, abre la PWA instalada desde la pantalla de inicio.');const config=await privateApi('/api/push/key');if(!config.publicKey)throw Error('El servidor todavía no tiene configuradas las notificaciones push.');const permission=await window.Notification.requestPermission();if(permission!=='granted')throw Error('No se concedió permiso para notificaciones.');const registration=await navigator.serviceWorker.ready;const pad='='.repeat((4-config.publicKey.length%4)%4),bytes=atob((config.publicKey+pad).replace(/-/g,'+').replace(/_/g,'/'));const subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:Uint8Array.from(bytes,c=>c.charCodeAt(0))});await privateApi('/api/push/subscriptions',{method:'POST',body:JSON.stringify(subscription.toJSON())});document.getElementById('research-message').textContent='Suscripción registrada. La entrega con la app cerrada depende del servidor y los permisos del dispositivo.';}catch(e){document.getElementById('research-message').textContent=e.message}}
function tickDashboard(){updateTransitionUI();document.querySelectorAll('[data-command-until]').forEach(el=>el.textContent=formatTime(Math.max(0,Number(el.dataset.commandUntil)*60-SebasPlanner.minute()*60-new Date().getUTCSeconds())));const m=SebasPlanner.minute();document.querySelectorAll('[data-kyiv-clock]').forEach(e=>e.textContent=SebasPlanner.time(m));document.querySelectorAll('[data-countdown]').forEach(e=>e.textContent=formatTime(Math.max(0,Number(e.dataset.target)-currentSeconds(e.dataset.countdown))));document.querySelectorAll('[data-timer-progress]').forEach(e=>e.style.width=Math.min(100,currentSeconds(e.dataset.timerProgress)/Number(e.dataset.target)*100)+'%');if(activeTab==='gym')updateGymUI();if(m!==lastDashboardMinute&&activeTab==='hoy'&&!pendingCompletion&&!openedFoodId){lastDashboardMinute=m;view('hoy')}}

let commandScrollDay='',commandScrollPosition=null,commandAutoFollow=true;
function commandItems(model){const list=model.items.filter(x=>x.id!=='trabajo'||model.current.id==='trabajo');const current=model.current;const idx=list.findIndex(x=>x.id===current.id&&(x.start===current.start||(current.kind==='active'&&x.start<=model.minute&&x.end>model.minute)));if(idx>=0)list[idx]={...list[idx],current:true};else list.push({...current,end:current.end||current.start+(current.duration||30),current:true});return list.sort((a,b)=>a.start-b.start)}
function activityBackground(item){const scene={despertar:'dawn',oracion:'prayer',gym:'training',lectura:'reading',ducha:'prepare',preparacion:'prepare',descanso:'rest',postcall:'rest',dormir:'rest'}[item.id]||'focus';return 'assets/scene-'+scene+'.webp'}
function commandDay(model){const items=commandItems(model);return `<section class="command-hero command-day" data-command-frame><div class="command-top"><span class="eyebrow">KPI · CENTRO DE MANDO</span><button class="command-now" onclick="jumpToNow()">Ahora <span data-kyiv-clock>${SebasPlanner.time(model.minute)}</span></button></div><div class="command-scroll" id="command-scroll" tabindex="0" role="region" aria-label="Agenda del día. Desliza hacia arriba o abajo" onscroll="commandScrollPosition=this.scrollTop" onwheel="commandAutoFollow=false" ontouchstart="commandAutoFollow=false" onkeydown="commandAutoFollow=false">${items.map((x,index)=>{const meal=mealForActivity(x.id),quiet=['descanso','postcall','despertar','dormir','ducha'].includes(x.id),title=x.kind==='event'&&SebasLife.isCommercial(x.event)?SebasOps.session(x.event,leadCard(x.event)).name:meal?meal.name:x.name;return `<article class="command-slide ${meal?'command-meal':''}" data-current="${!!x.current}" style="background-image:linear-gradient(90deg,#070c16dc,#070c1640),linear-gradient(0deg,#070c1680,transparent),url('${meal?mealImage(meal.type,meal):activityBackground(x)}')"><div class="now-label">${x.current?'AHORA':SebasPlanner.time(x.start)+(Number.isFinite(x.end)?'–'+SebasPlanner.time(x.end):'')}${meal?' · '+FOOD_LABELS[meal.type]:''}</div><h2>${esc(title)}</h2>${x.id==='klimb'?(data.klimbTasks||[]).filter(t=>t.id===data.klimbFocusTask&&!t.done).map(t=>'<p class="command-context">'+esc(t.title)+'</p>').join(''):''}${x.id==='desayuno'?'<small class="command-meal-timing">10 min preparar · 15 min desayunar</small>':''}${x.current?commandMainClock(x):''}${x.current&&x.id==='libre'?'<button class="quick-command" onclick="markRestCompleted()">Ya descansé</button><button class="quick-command" onclick="chooseSmartActivity(\'seguimientos\')">Estoy haciendo seguimientos</button>':''}${quiet?'':`<button class="command-cta" onclick="openCommandItem(${index})">${meal?'Ver receta':x.id==='libre'?'Elegir actividad':'Ver actividad'}<span aria-hidden="true">↗</span></button>`}${x.id==='cena'?'<button class="quick-command" onclick="quickDinner()">Sin tiempo · cena rápida</button>':''}</article>`}).join('')}</div><footer class="command-footer">${transitionPanel()}</footer><div class="command-scroll-hint">↕ Recorre tu día</div></section>`}
function openCommandItem(index){const item=commandItems(dashboardCommand())[index];if(!item)return;if(item.event)openEvent(SebasCore.eventKey(item.event));else {const meal=mealForActivity(item.id);if(meal)openFood(meal.id);else if(item.id==='libre')openSmartActivity();else openActivity(item.id)}}
function restoreCommandScroll(){const el=document.getElementById('command-scroll');if(!el?.querySelector)return;if(commandScrollDay!==kyivDay()){commandScrollDay=kyivDay();commandScrollPosition=null;commandAutoFollow=true}const current=el.querySelector('[data-current="true"]');el.scrollTop=commandAutoFollow?(current?current.offsetTop:0):(commandScrollPosition??0)}
function jumpToNow(){commandAutoFollow=true;commandScrollPosition=null;restoreCommandScroll()}
let bedtimeAudio=null,bedtimeChimeTimer=null;
function bedtimeSettings(){return `<section class="card"><div class="sectiontop"><h2>Dormir</h2><span class="eventpill">23:30 · Kyiv</span></div><p class="muted">Aviso en pantalla con la app abierta. No suena con la app cerrada ni puede saltarse el silencio del iPhone.</p><button onclick="enableBedtimeSound()">Activar y probar sonido</button><p id="bedtime-sound-status" role="status"></p></section>`}
async function enableBedtimeSound(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error('Sonido no disponible en este navegador.');bedtimeAudio??=new Audio();await bedtimeAudio.resume();if(bedtimeAudio.state!=='running')throw Error('El navegador ha bloqueado el sonido.');data.bedtimeSound=true;save();playBedtimeChime();document.getElementById('bedtime-sound-status').textContent='Sonido activado en esta sesión, con la app abierta.'}catch(e){const status=document.getElementById('bedtime-sound-status');if(status)status.textContent=e.message}}
function playBedtimeChime(){if(!bedtimeAudio||bedtimeAudio.state!=='running')return;[523.25,659.25,783.99].forEach((frequency,i)=>{const oscillator=bedtimeAudio.createOscillator(),gain=bedtimeAudio.createGain(),start=bedtimeAudio.currentTime+i*.35;oscillator.type='sine';oscillator.frequency.value=frequency;gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(.16,start+.03);gain.gain.exponentialRampToValueAtTime(.001,start+.8);oscillator.connect(gain);gain.connect(bedtimeAudio.destination);oscillator.start(start);oscillator.stop(start+.85)})}
function tickBedtime(){if(SebasPlanner.minute()<1410||document.visibilityState!=='visible'||data.bedtimeDismissed===kyivDay()||document.getElementById('bedtime-dialog')?.open)return;const d=document.createElement('dialog');if(!d.showModal)return;d.id='bedtime-dialog';d.className='sale-dialog bedtime-dialog';d.setAttribute('aria-labelledby','bedtime-title');d.innerHTML='<span class="eyebrow">23:30 · HORA DE DORMIR</span><div class="bedtime-moon">☾</div><h2 id="bedtime-title">Por hoy, ya está.</h2><p>Es momento de dormir, Sebastián.</p><button onclick="dismissBedtime()">Me voy a dormir</button>';d.addEventListener('cancel',e=>{e.preventDefault();dismissBedtime()});document.body.append(d);d.showModal();const chime=()=>{if(!d.isConnected)return;if(data.bedtimeSound)playBedtimeChime();bedtimeChimeTimer=setTimeout(chime,8000)};chime()}
function dismissBedtime(){clearTimeout(bedtimeChimeTimer);document.getElementById('bedtime-dialog')?.remove();data.bedtimeDismissed=kyivDay();save()}

function scheduleTransition(now=Date.now()){return SebasOps.transition(SebasLife.scheduledEvents(effectiveEvents(),allLeadCards()),activeTrack,now,plannerOptions())}
function transitionCopy(t){if(t.state==='idle')return {label:'SIN MÁS CAMBIOS',detail:t.name};if(t.state==='overdue')return {label:'CAMBIO DE ACTIVIDAD',detail:'Ya toca · '+t.name};return {label:'SIGUIENTE · '+SebasPlanner.time(t.target.start),detail:t.name+' · '+formatTime(Math.max(0,t.seconds))}}
function transitionPanel(){const t=scheduleTransition(),c=transitionCopy(t);return `<div class="transition-cue" data-transition-state="${t.state}"><div><span data-transition-label>${esc(c.label)}</span><strong data-transition-detail>${esc(c.detail)}</strong></div><button aria-label="Ver siguiente actividad" class="transition-open" onclick="openTransition()" ${t.target?'':'hidden'}>↗</button><div class="transition-bar" role="progressbar" aria-label="Proximidad del cambio de actividad" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(t.ratio*100)}"><span style="width:${t.ratio*100}%"></span></div></div>`}
function activeTimerRail(){if(!activeTrack)return '';const track=TRACKS.find(t=>t.id===activeTrack.id);return `<div class="active-timer-rail"><span class="timer-dot"></span><div><small>CRONÓMETRO EN CURSO</small><strong>${esc(track?.name||activeTrack.id)}</strong></div><b data-track-seconds="${activeTrack.id}">${formatTime(currentSeconds(activeTrack.id))}</b><button class="rail-control" onclick="pauseTrack()" aria-label="Pausar cronómetro">Ⅱ</button><button class="rail-control" onclick="openActivity('${activeTrack.id}')" aria-label="Abrir cronómetro">↗</button></div>`}
function openTransition(){const t=scheduleTransition();if(!t.target)return;if(t.target.event)openEvent(SebasCore.eventKey(t.target.event));else {const meal=mealForActivity(t.target.id);if(meal)openFood(meal.id);else if(['descanso','postcall','despertar','dormir','ducha'].includes(t.target.id))jumpToNow();else openActivity(t.target.id)}}
function updateTransitionUI(){const t=scheduleTransition(),c=transitionCopy(t);document.querySelectorAll('[data-transition-state]').forEach(el=>{el.dataset.transitionState=t.state;const label=el.querySelector('[data-transition-label]'),detail=el.querySelector('[data-transition-detail]'),bar=el.querySelector('[role="progressbar"]');if(label)label.textContent=c.label;if(detail)detail.textContent=c.detail;if(bar){bar.setAttribute('aria-valuenow',Math.round(t.ratio*100));bar.firstElementChild.style.width=t.ratio*100+'%'}});document.querySelectorAll('[data-command-frame]').forEach(el=>el.dataset.urgency=t.state);document.querySelectorAll('[data-next-watermark]').forEach(el=>{el.hidden=!['amber','red','overdue'].includes(t.state);el.querySelector('[data-watermark-label]').textContent=t.state==='overdue'?'Ahora toca':'Siguiente';el.querySelector('[data-watermark-name]').textContent=t.name})}
function moreDashboard(){return `<section class="card"><span class="eyebrow">TU ESPACIO</span><h2>Más</h2><div class="more-grid">${[['calendario','Calendario','▦'],['comidas','Comidas','♧'],['gym','Entrenamiento','↗'],['lectura','Lectura','▤'],['habitos','Hábitos','✓'],['estadisticas','Estadísticas','◴'],['ajustes','Ajustes y conexiones','⚙']].map(([id,name,icon])=>`<button onclick="view('${id}')"><span>${icon}</span><strong>${name}</strong><small>Abrir ↗</small></button>`).join('')}</div></section>`}

function settingsDashboard(){return `<section class="card"><span class="eyebrow">A TU MEDIDA</span><h2>Ajustes</h2><div class="settings-status"><span class="status-dot ${googleToken?'connected':''}"></span><div><strong>Google Calendar</strong><small>${esc(googleStatus)}</small></div></div><div class="settings-status"><span class="status-dot ${recapDevice?'connected':''}"></span><div><strong>Agenda ChatGPT</strong><small>${esc(recapState.status)}</small></div></div><div class="settings-status"><span class="status-dot ${slackConnection.connected?'connected':''}"></span><div><strong>Slack</strong><small>${esc(slackConnection.message)}</small></div></div></section><details class="card" ${sectionAttrs('settings-connect')}><summary>Conexiones y notificaciones</summary>${recapSettings()+calendarSettings()}<details class="slack-service-advanced"><summary>Slack directo · conexión opcional</summary>${slackSettings()}</details><details class="slack-service-advanced"><summary>Configuración del servicio privado</summary>${researchSettings()}</details><p class="muted">ChatGPT: pendiente de conexión segura.</p></details><details class="card" ${sectionAttrs('settings-plan')}><summary>Planificación y hora de dormir</summary>${routineSettings()}</details><details class="card" ${sectionAttrs('settings-goals')}><summary>Modificar metas de actividades</summary>${goalSettings()}</details>`}

function nextWatermark(){const t=scheduleTransition(),visible=['amber','red','overdue'].includes(t.state);return `<div class="next-watermark" data-next-watermark ${visible?'':'hidden'}><span data-watermark-label>${t.state==='overdue'?'Ahora toca':'Siguiente'}</span><strong data-watermark-name>${esc(t.name)}</strong></div>`}

function commandMainClock(item){if(activeTrack){return `<div class="command-main-timer"><span data-track-seconds="${activeTrack.id}">${formatTime(currentSeconds(activeTrack.id))}</span><small>Cronómetro · ${esc(TRACKS.find(t=>t.id===activeTrack.id)?.name||'')}</small><div class="command-timer-controls"><button aria-label="Pausar cronómetro" onclick="pauseTrack()">Ⅱ</button><button onclick="finishTrack('${activeTrack.id}')">Terminar</button></div></div>`}const track=TRACKS.find(t=>t.id===item.id);if(track&&trackData(track.id).done)return '<div class="command-main-timer"><span>✓</span><small>Completado</small></div>';if(track)return `<div class="command-main-timer"><span>${formatTime(Math.max(0,(item.duration||track.goal)*60-currentSeconds(track.id)))}</span><button class="command-start" onclick="${track.id==='gym'?'startWorkout()':`beginTrack('${track.id}')`}">▶ Iniciar</button></div>`;if(Number.isFinite(item.end))return `<div class="command-main-timer"><span data-command-until="${item.end}">${formatTime(Math.max(0,item.end*60-SebasPlanner.minute()*60-new Date().getUTCSeconds()))}</span><small>Hasta las ${SebasPlanner.time(item.end)}</small></div>`;return ''}
